  el('wallet-setup-back').onclick=()=>{el('wallet-setup-form').hidden=true;el('first-profile-form').hidden=false;el('wallet-setup-status').textContent='';el('first-wallet-secret').textContent='';pendingWallet=null;};
  el('first-profile-signout').onclick=async()=>{try{await api('/api/auth/logout','POST',{});}catch{}window.localStorage.removeItem('nsatToken');window.sessionStorage.removeItem('nsatToken');location.reload();};
  el('profile-open').onclick=async()=>{const dialog=el('profile-dialog');if(!dialog.open)dialog.showModal();el('profile-status').textContent='Loading profile…';try{await loadMyProfile();el('profile-username').value=myProfile.username;el('profile-name').value=myProfile.displayName;el('profile-phone').value=myProfile.phone||'';el('profile-bio').value=myProfile.bio||'';el('profile-status-message').value=myProfile.statusMessage||'';for(const field of ['phone','bio','statusMessage','coverPhoto','birthday','website','city','work','education','relationship']){const visibility=visibilityInput(field);if(visibility)visibility.value=myProfile[`${field}Visibility`]||(['bio','statusMessage','coverPhoto'].includes(field)?'everyone':'only_me');}el('profile-birthday').value=myProfile.birthday||'';el('profile-website').value=myProfile.website||'';el('profile-city').value=myProfile.city||'';el('profile-work').value=myProfile.work||'';el('profile-education').value=myProfile.education||'';el('profile-relationship').value=myProfile.relationship||'';el('profile-birthday').max=new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,10);el('profile-wallet-address').textContent=myProfile.walletAddress||'No wallet is linked to this profile.';el('profile-wallet-backup').textContent=myProfile.walletAddress?(myProfile.walletBackupConfirmed?'Recovery key backup confirmed':'Wallet backup not confirmed'):'No wallet has been created on this account.';el('profile-wallet-address').hidden=!myProfile.walletAddress;el('profile-wallet-address-copy').hidden=!myProfile.walletAddress;el('profile-wallet-reveal').hidden=!myProfile.walletAddress;el('profile-wallet-restore').hidden=!myProfile.walletAddress;el('profile-wallet-restore-form').hidden=true;el('profile-wallet-copy').hidden=true;el('profile-wallet-reveal-form').hidden=true;el('profile-wallet-key').hidden=true;el('profile-wallet-key').textContent='';profileAvatar=myProfile.avatar||'';profileCover=myProfile.coverPhoto||'';const preview=el('profile-preview');const src=profileAvatar||myProfile.avatarUrl;if(src){preview.src=src;preview.hidden=false;}else preview.hidden=true;const coverPreview=el('profile-cover-preview');if(profileCover){coverPreview.src=profileCover;coverPreview.hidden=false;}else coverPreview.hidden=true;el('profile-status').textContent='';}catch(error){el('profile-status').textContent=error.message;}};
  el('profile-wallet-address-copy').onclick=async()=>{try{await navigator.clipboard.writeText(myProfile.walletAddress);el('profile-wallet-status').textContent='Wallet address copied.';}catch{el('profile-wallet-status').textContent='Could not copy automatically. Select and copy the wallet address.';}};
