  el('profile-wallet-restore').onclick=()=>{el('profile-wallet-restore-form').hidden=false;el('profile-wallet-recovery').focus();};
  el('profile-wallet-restore-submit').onclick=async()=>{const secret=el('profile-wallet-recovery').value.trim().toUpperCase(),password=el('profile-wallet-restore-password').value;if(password!==el('profile-wallet-restore-confirm').value){el('profile-wallet-status').textContent='The wallet passwords do not match.';return;}el('profile-wallet-status').textContent='Checking and encrypting recovery key on this device…';try{const address=await walletAddressForRecoveryKey(secret);if(address!==myProfile.walletAddress)throw new Error('wallet_address_mismatch');await saveEncryptedWallet(secret,password,address);el('profile-wallet-recovery').value='';el('profile-wallet-restore-password').value='';el('profile-wallet-restore-confirm').value='';el('profile-wallet-restore-form').hidden=true;el('profile-wallet-restore').hidden=true;el('profile-wallet-status').textContent='Wallet restored and encrypted on this device.';}catch(error){el('profile-wallet-status').textContent=error.message==='wallet_password_invalid'?'Use a wallet password with at least 10 characters.':error.message==='wallet_address_mismatch'?'That recovery key does not match this account’s wallet address.':'Could not restore that recovery key. Check the key and try again.';}};
