  el('profile-dialog').addEventListener('close',()=>{el('profile-wallet-key').textContent='';el('profile-wallet-password').value='';});
  el('profile-photo').onchange=async event=>{const file=event.target.files?.[0];if(!file)return;el('profile-status').textContent='Preparing photo…';try{profileAvatar=await compressAvatar(file);el('profile-preview').src=profileAvatar;el('profile-preview').hidden=false;el('profile-status').textContent='Profile photo ready';}catch(error){el('profile-status').textContent=error.message;}finally{event.target.value='';}};
  el('profile-cover-photo').onchange=async event=>{const file=event.target.files?.[0];if(!file)return;el('profile-status').textContent='Preparing cover photo…';try{profileCover=await compressCover(file);el('profile-cover-preview').src=profileCover;el('profile-cover-preview').hidden=false;el('profile-status').textContent='Cover photo ready';}catch(error){el('profile-status').textContent=error.message;}finally{event.target.value='';}};
  el('profile-form').onsubmit=async event=>{event.preventDefault();el('profile-status').textContent='Saving…';try{const fields={username:el('profile-username').value.trim().toLowerCase(),displayName:el('profile-name').value.trim(),phone:el('profile-phone').value.trim(),bio:el('profile-bio').value.trim(),statusMessage:el('profile-status-message').value.trim(),birthday:el('profile-birthday').value,website:el('profile-website').value.trim(),city:el('profile-city').value.trim(),work:el('profile-work').value.trim(),education:el('profile-education').value.trim(),relationship:el('profile-relationship').value,avatar:profileAvatar,coverPhoto:profileCover};for(const field of ['phone','bio','statusMessage','coverPhoto','birthday','website','city','work','education','relationship'])fields[`${field}Visibility`]=visibilityInput(field).value;const result=await api('/api/me','PATCH',fields);myProfile=result.profile;el('who').textContent=`${myProfile.displayName} · @${myProfile.username}`;el('profile-dialog').close();}catch(error){el('profile-status').textContent=error.message;}};
