async function makePeer(id,mode,offer,attempt=callAttempt){targetId=id;callMode=mode;pendingIce=[];const stream=await getMedia(mode,cameraFacing);if(attempt!==callAttempt){stream.getTracks().forEach(track=>track.stop());return false;}localStream=stream;pc=new RTCPeerConnection({iceServers:config.iceServers});const videoTrack=mode==='video'?startVideoEffects(localStream):null;localStream.getAudioTracks().forEach(track=>pc.addTrack(track,localStream));if(videoTrack)pc.addTrack(videoTrack,effectStream||localStream);pc.ontrack=event=>{remoteStream=event.streams?.[0]||new MediaStream([event.track]);el('remote').muted=true;el('remote').srcObject=remoteStream;el('remote-audio').srcObject=remoteStream;el('remote').play().catch(()=>{});el('remote-audio').play().then(()=>{el('enable-call-media').hidden=true;}).catch(()=>{el('enable-call-media').hidden=false;});event.track.onunmute=()=>el('remote').classList.remove('video-muted');};pc.onicecandidate=event=>{if(event.candidate)sendSignal('ice',event.candidate);};pc.onicecandidateerror=event=>{console.warn('ICE candidate error',event.errorCode,event.errorText);};pc.oniceconnectionstatechange=()=>{if(!pc)return;const state=pc.iceConnectionState;if(state==='checking')setCallStatus('Connecting…');else if(state==='connected'||state==='completed')setCallStatus('Connected');else if(state==='disconnected')setCallStatus('Reconnecting…');else if(state==='failed')setCallStatus('Network path failed. A TURN relay may be required on mobile networks.');};pc.onconnectionstatechange=async()=>{if(!pc)return;const connection=pc.connectionState;if(connection==='connected'){iceRestartCount=0;markCallConnected();return;}if(connection==='connecting'){setCallStatus('Connecting…');return;}if(connection==='disconnected'){setCallStatus('Reconnecting…');clearTimeout(callDisconnectTimer);callDisconnectTimer=setTimeout(()=>{if(pc?.connectionState==='disconnected')endCall(true,'Connection lost');},10000);return;}if(connection==='failed'){if(iceRestartCount>=2){setCallStatus('Network path failed. Ending call…');clearTimeout(callDisconnectTimer);callDisconnectTimer=setTimeout(()=>{if(pc?.connectionState==='failed')endCall(true,'No network route. A TURN relay may be required.');},5000);return;}setCallStatus('Mobile network path failed; retrying. TURN may be required.');const retry=++iceRestartCount;clearTimeout(callDisconnectTimer);callDisconnectTimer=setTimeout(async()=>{if(!pc||pc.connectionState==='connected')return;try{if(pc.signalingState==='stable'){await pc.restartIce();await createAndSendOffer(true);}if(pc?.connectionState==='failed')pc.onconnectionstatechange?.();}catch{if(pc?.connectionState==='failed')endCall(true,'No network route. A TURN relay may be required.');}},800*2**(retry-1));}};
  await applyCallQuality();
  if(offer){await setRemoteDescription(offer);const answer=await pc.createAnswer();await pc.setLocalDescription(answer);sendSignal('answer',pc.localDescription);setCallStatus('Connecting…');}else{await createAndSendOffer();armCallTimeout();}return true;
}
async function startCall(id,mode='video'){if(pc||targetId||!socket?.connected)return;const attempt=++callAttempt;callReturnView='chats';callReturnScreen='conversation';const peer=peers.find(item=>item.id===id);callName=peer?.user?.name||'Member';activeCallQuality=callQuality;networkBadSamples=networkGoodSamples=0;lastCallPacketStats.clear();activeCallLogId=addCallHistory(peer?.user?.id||'',callName,mode,'outgoing');callStartedAt=0;beginCallView(mode,callName,'Requesting access…');clearTimeout(callMediaTimer);callMediaTimer=setTimeout(()=>{if(attempt===callAttempt&&!pc)endCall(false,'Camera or microphone permission timed out.');},30000);try{const started=await makePeer(id,mode,undefined,attempt);clearTimeout(callMediaTimer);if(started&&attempt===callAttempt)setCallStatus('Calling…');}catch(error){clearTimeout(callMediaTimer);if(attempt===callAttempt)endCall(false,userFacingCallError(error));}}
async function acceptIncomingCall(){if(!incomingOffer)return;const pending=incomingOffer;incomingOffer=null;activeCallLogId=pending.historyId;updateCallHistory(activeCallLogId,{status:'calling'});el('call-incoming-dialog').close();const attempt=++callAttempt;callName=pending.name;activeCallQuality=callQuality;networkBadSamples=networkGoodSamples=0;lastCallPacketStats.clear();callStartedAt=0;beginCallView(pending.mode,callName,'Requesting access…');clearTimeout(callMediaTimer);callMediaTimer=setTimeout(()=>{if(attempt===callAttempt&&!pc)endCall(false,'Camera or microphone permission timed out.');},30000);try{const started=await makePeer(pending.from,pending.mode,pending.offer,attempt);clearTimeout(callMediaTimer);if(!started||attempt!==callAttempt)sendSignalTo(pending.from,'decline');}catch(error){clearTimeout(callMediaTimer);if(attempt===callAttempt){sendSignalTo(pending.from,'decline');endCall(false,userFacingCallError(error));}}}
function declineIncomingCall(autoMissed=false){const hadIncoming=!!incomingOffer;if(incomingOffer){sendSignalTo(incomingOffer.from,'decline');updateCallHistory(incomingOffer.historyId,{status:autoMissed?'missed':'declined',endedAt:new Date().toISOString()});if(activeCallLogId===incomingOffer.historyId)activeCallLogId=null;}incomingOffer=null;clearTimeout(callTimeoutTimer);if(el('call-incoming-dialog').open)el('call-incoming-dialog').close();if(hadIncoming)endCall(false,autoMissed?'No answer':'Call declined');}
function sendSignalTo(id,type,data){if(socket?.connected&&id)socket.emit('webrtc',{to:id,type,data,mode:callMode});}
function sendSignal(type,data){if(socket?.connected&&targetId)sendSignalTo(targetId,type,data);}
async function signal(packet){
  if(packet.type==='offer'){
    if(pc){if(packet.from!==targetId){sendSignalTo(packet.from,'decline');return;}await setRemoteDescription(packet.data);const answer=await pc.createAnswer();await pc.setLocalDescription(answer);sendSignal('answer',pc.localDescription);return;}
    if(incomingOffer){sendSignalTo(packet.from,'decline');return;}
    const peer=peers.find(item=>item.id===packet.from);const mode=packet.mode==='audio'?'audio':'video',name=peer?.user?.name||'Member',historyId=addCallHistory(peer?.user?.id||'',name,mode,'incoming');incomingOffer={from:packet.from,mode,offer:packet.data,name,historyId};callReturnView='chats';callReturnScreen='conversation';beginCallView(incomingOffer.mode,incomingOffer.name,'Incoming call');el('incoming-call-title').textContent=incomingOffer.name;el('incoming-call-mode').textContent=incomingOffer.mode==='audio'?'Incoming voice call':'Incoming video call';el('call-incoming-dialog').showModal();callTimeoutTimer=setTimeout(()=>declineIncomingCall(true),45000);return;
  }
  if(packet.from!==targetId){if(incomingOffer?.from===packet.from&&['hangup','decline'].includes(packet.type)){updateCallHistory(incomingOffer.historyId,{status:packet.type==='hangup'?'missed':'cancelled',endedAt:new Date().toISOString()});if(activeCallLogId===incomingOffer.historyId)activeCallLogId=null;incomingOffer=null;clearTimeout(callTimeoutTimer);if(el('call-incoming-dialog').open)el('call-incoming-dialog').close();endCall(false,packet.type==='hangup'?'Call ended':'Call declined');}return;}
  if(packet.type==='answer'&&pc){await setRemoteDescription(packet.data);setCallStatus('Connecting…');}
  else if(packet.type==='ice'&&pc){if(pc.remoteDescription)await pc.addIceCandidate(packet.data).catch(()=>{});else pendingIce.push(packet.data);}
  else if(packet.type==='decline'){endCall(false,'Call declined');}
  else if(packet.type==='hangup'){endCall(false,'Call ended');}
}
async function replaceVideoDevice(deviceId){if(!pc||callMode!=='video'||screenStream)throw new Error('Camera selection is unavailable right now.');const profile=callQualityProfiles[activeCallQuality]||callQualityProfiles.saver;const nextStream=await navigator.mediaDevices.getUserMedia({audio:false,video:{deviceId:{exact:deviceId},width:{ideal:profile.width},height:{ideal:profile.height},frameRate:{ideal:profile.fps,max:profile.fps}}});const nextTrack=nextStream.getVideoTracks()[0];nextTrack.enabled=cameraEnabled;const oldTrack=localStream.getVideoTracks()[0];const audioTracks=localStream.getAudioTracks();const sender=pc.getSenders().find(item=>item.track?.kind==='video');const nextLocal=new MediaStream([...audioTracks,nextTrack]);const processed=startVideoEffects(nextLocal);if(effectStream)effectStream.getVideoTracks().forEach(track=>track.enabled=cameraEnabled);await sender.replaceTrack(processed);localStream=nextLocal;oldTrack?.stop();preferredCameraId=deviceId;cameraFacing=nextTrack.getSettings().facingMode||cameraFacing;}
async function changeCameraDevice(deviceId){try{await replaceVideoDevice(deviceId);el('call-options-note').textContent='Camera changed.';}catch(error){el('call-options-note').textContent=`Could not change camera: ${error.message}`;await populateCallOptions();}}
async function changeMicrophoneDevice(deviceId){try{const nextStream=await navigator.mediaDevices.getUserMedia({audio:{deviceId:{exact:deviceId},echoCancellation:true,noiseSuppression:noiseSuppressionEnabled,autoGainControl:true},video:false});const nextTrack=nextStream.getAudioTracks()[0];const oldTrack=localStream.getAudioTracks()[0];nextTrack.enabled=oldTrack?.enabled??true;const sender=pc?.getSenders().find(item=>item.track?.kind==='audio');if(!sender)throw new Error('Microphone track is unavailable.');await sender.replaceTrack(nextTrack);localStream=new MediaStream([...localStream.getVideoTracks(),nextTrack]);oldTrack?.stop();preferredMicrophoneId=deviceId;el('call-options-note').textContent='Microphone changed.';}catch(error){el('call-options-note').textContent=`Could not change microphone: ${error.message}`;await populateCallOptions();}}
async function switchCamera(){if(!pc||callMode!=='video'||screenStream)return;const nextFacing=cameraFacing==='user'?'environment':'user',profile=callQualityProfiles[activeCallQuality]||callQualityProfiles.saver;try{const nextStream=await navigator.mediaDevices.getUserMedia({audio:false,video:{facingMode:{exact:nextFacing},width:{ideal:profile.width},height:{ideal:profile.height},frameRate:{ideal:profile.fps,max:profile.fps}}});const id=nextStream.getVideoTracks()[0].getSettings().deviceId;nextStream.getTracks().forEach(track=>track.stop());preferredCameraId='';await replaceVideoDevice(id);preferredCameraId=id;el('camera-input-select').value=id;el('call-options-note').textContent='';showCallControls();}catch(error){el('call-options-note').textContent=error.name==='OverconstrainedError'?'This device cannot switch to that camera.':`Could not switch camera: ${error.message}`;}}
async function populateCallOptions(){el('call-options-note').textContent='';const share=el('screen-share');share.hidden=!pc||callMode!=='video'||(!screenStream&&!navigator.mediaDevices?.getDisplayMedia);share.textContent=screenStream?'Stop sharing screen':'Share screen';const audio=el('audio-output');const outputRow=el('audio-output-row');const outputSelect=el('audio-output-select');const videoRow=el('camera-input-row');const microphoneRow=el('microphone-input-row');if(!navigator.mediaDevices?.enumerateDevices){audio.hidden=true;outputRow.hidden=true;videoRow.hidden=true;microphoneRow.hidden=true;return;}try{const devices=await navigator.mediaDevices.enumerateDevices();const fill=(select,items,current,label)=>{select.replaceChildren();items.forEach((device,index)=>{const option=document.createElement('option');option.value=device.deviceId;option.textContent=device.label||`${label} ${index+1}`;select.append(option);});select.value=current&&items.some(item=>item.deviceId===current)?current:(items[0]?.deviceId||'');return items.length>0;};const cameras=devices.filter(device=>device.kind==='videoinput'),microphones=devices.filter(device=>device.kind==='audioinput'),speakers=devices.filter(device=>device.kind==='audiooutput');videoRow.hidden=!pc||callMode!=='video'||screenStream||!fill(el('camera-input-select'),cameras,localStream?.getVideoTracks()[0]?.getSettings().deviceId||preferredCameraId,'Camera');microphoneRow.hidden=!pc||!fill(el('microphone-input-select'),microphones,localStream?.getAudioTracks()[0]?.getSettings().deviceId||preferredMicrophoneId,'Microphone');const outputAvailable=typeof el('remote-audio').setSinkId==='function'&&fill(outputSelect,speakers,preferredSpeakerId,'Speaker');audio.hidden=!outputAvailable;outputRow.hidden=!outputAvailable;}catch(error){audio.hidden=true;outputRow.hidden=true;videoRow.hidden=true;microphoneRow.hidden=true;el('call-options-note').textContent=`Could not list call devices: ${error.message}`;}}
async function toggleScreenShare(){if(screenStream){stopScreenShare();return;}if(!pc||callMode!=='video'||!navigator.mediaDevices?.getDisplayMedia)return;try{const stream=await navigator.mediaDevices.getDisplayMedia({video:true,audio:false});const track=stream.getVideoTracks()[0];const sender=pc.getSenders().find(item=>item.track?.kind==='video');if(!sender)throw new Error('No outgoing video track is available.');if(effectTimer)clearTimeout(effectTimer);effectTimer=null;effectStream?.getTracks().forEach(item=>item.stop());effectStream=null;screenStream=stream;await sender.replaceTrack(track);el('local').srcObject=screenStream;track.onended=stopScreenShare;el('call-options-note').textContent='Screen sharing is on.';showCallControls();}catch(error){el('call-options-note').textContent=`Screen sharing stopped: ${userFacingCallError(error)}`;}}
function stopScreenShare(){if(!screenStream)return;const current=screenStream;screenStream=null;current.getTracks().forEach(track=>track.stop());if(!pc||!localStream)return;const track=startVideoEffects(localStream);const sender=pc.getSenders().find(item=>item.track?.kind==='video');sender?.replaceTrack(track).then(()=>{el('call-options-note').textContent='Camera restored.';}).catch(error=>{el('call-options-note').textContent=`Could not restore camera: ${error.message}`;});populateCallOptions();}
function clampPip(){const stage=el('call-stage');for(const video of [el('local'),el('remote')]){if(!video.style.left&&!video.style.top)continue;const box=stage.getBoundingClientRect();video.style.left=`${Math.max(8,Math.min(box.width-video.offsetWidth-8,parseFloat(video.style.left)||8))}px`;video.style.top=`${Math.max(8,Math.min(box.height-video.offsetHeight-8,parseFloat(video.style.top)||8))}px`;}}
async function registerServiceWorker(){if(!('serviceWorker'in navigator))return;try{serviceWorkerRegistration=await navigator.serviceWorker.register('/service-worker.js');}catch(error){console.warn('Service worker registration failed',error);}}
function showForegroundNotification(message){if(typeof Notification==='undefined'||Notification.permission!=='granted'||document.visibilityState==='visible')return;const title=message.sender?.name||'New message';serviceWorkerRegistration?.showNotification(title,{body:'You have a new message',icon:'/nsat-icon.svg',tag:`message-${message.room}`,data:{room:message.room}}).catch(()=>{});}
